#!/bin/bash
# Generated by study-lab export --target killercoda. Do not edit: change the lab and export again.
LAB=/opt/study-lab/democert-1.1
mkdir -p "$LAB"
trap 'touch /tmp/finished' EXIT
for i in $(seq 1 60); do [ -f /root/break_fix.sh ] && break; sleep 1; done
[ -f /root/break_fix.sh ] && mv /root/break_fix.sh "$LAB/"
export I_UNDERSTAND_THIS_IS_A_DISPOSABLE_VM=yes
export LAB_DISPOSABLE=yes
export STUDY_LAB=1
cd "$LAB" || exit 1
# break is idempotent by contract; a fresh cluster can still be settling (e.g. the default ServiceAccount), so retry
for attempt in 1 2 3; do
  timeout 300 bash ./break_fix.sh break </dev/null > "$LAB/break.out" 2>&1 && ok=1 && break
  sleep 10
done
[ "${ok:-}" = 1 ] || { echo failed > /tmp/study-lab-setup-failed; cat "$LAB/break.out"; }
